$ErrorActionPreference='Stop'
$taskExtractionPath='records/prototype_v7_partial_review_001/extraction_receipt.json'
$taskNativePath='records/prototype_v7_partial_native_001/run_001/partial_native_receipt.json'
$taskPins=@{$taskExtractionPath='9bf40771df6dd7f67189d402d6bcfd8e05bd8cd997b71a6825fff21da105ae98';$taskNativePath='bc700054e18dad6de9e2516f441adccdfac0a9ace25a39fd0fce6a0879d37f4f'}
foreach($taskP in $taskPins.Keys){if((Get-FileHash -Algorithm SHA256 -LiteralPath $taskP).Hash.ToLower() -ne $taskPins[$taskP]){throw 'RECEIPT_PIN_MISMATCH'}}
$taskExtraction=Get-Content -Raw -LiteralPath $taskExtractionPath|ConvertFrom-Json -AsHashtable
$taskNative=Get-Content -Raw -LiteralPath $taskNativePath|ConvertFrom-Json -AsHashtable
$taskInputRoot=(Resolve-Path -LiteralPath 'records/prototype_v7_partial_review_001/extracted_001').Path
$taskMembers=@{}
function Read-TaskMember([string]$member){$taskFile=Join-Path $taskInputRoot $member;$taskEntry=$taskExtraction.inventory[$member];if($null -eq $taskEntry -or !(Test-Path -LiteralPath $taskFile -PathType Leaf)){throw ('MISSING_MEMBER:'+$member)};$taskHash=(Get-FileHash -Algorithm SHA256 -LiteralPath $taskFile).Hash.ToLower();if($taskHash -ne $taskEntry.sha256 -or (Get-Item -LiteralPath $taskFile).Length -ne $taskEntry.bytes){throw ('MEMBER_BYTES_CHANGED:'+$member)};$taskMembers[$member]=$taskHash;return (Get-Content -Raw -LiteralPath $taskFile|ConvertFrom-Json -AsHashtable)}
function Assert-TaskSeconds($value){if(($value -isnot [double] -and $value -isnot [long] -and $value -isnot [int]) -or ![double]::IsFinite($value) -or $value -lt 0){throw 'INVALID_RECORDED_SECONDS'}}
$taskRows=@();$taskArms=@()
for($taskI=0;$taskI -lt 72;$taskI++){$taskMember='cloud_job/campaign/native/evaluation/case_'+$taskI.ToString('0000')+'/case_receipt.json';if($taskI -eq 45){if($taskExtraction.inventory.Contains($taskMember) -or (Test-Path -LiteralPath (Join-Path $taskInputRoot $taskMember))){throw 'UNEXPECTED_CASE45_COMPLETION'};continue};$taskCase=Read-TaskMember $taskMember;if($taskCase.case_index -ne $taskI -or $taskCase.task_id -ne $taskNative.outcomes.cases[$taskI].task_id){throw 'CASE_MAPPING_CHANGED'};Assert-TaskSeconds $taskCase.case_wall_seconds;Assert-TaskSeconds $taskCase.reference_wall_seconds;$taskSum=0.0;foreach($taskArm in @('cas_untrained','cas_trained','generic_untrained','generic_trained','rule')){$taskRow=$taskCase.arms[$taskArm];Assert-TaskSeconds $taskRow.wall_seconds;if($taskRow.execution_status -ne $taskNative.outcomes.cases[$taskI].arms[$taskArm].execution_status){throw 'STATUS_MAPPING_CHANGED'};$taskSum+=$taskRow.wall_seconds;$taskArms+=@{case_index=$taskI;arm=$taskArm;status=$taskRow.execution_status;wall_seconds=$taskRow.wall_seconds}};$taskResidual=$taskCase.case_wall_seconds-$taskCase.reference_wall_seconds-$taskSum;if($taskResidual -lt -0.000001){throw 'CASE_TIME_COMPONENTS_EXCEED_TOTAL'};$taskRows+=@{case_index=$taskI;case_wall_seconds=$taskCase.case_wall_seconds;reference_wall_seconds=$taskCase.reference_wall_seconds;summed_arm_seconds=$taskSum;outside_arm_and_reference_seconds=$taskResidual;member=$taskMember}}
$taskCase45=@()
foreach($taskArm in @('cas_untrained','cas_trained','generic_untrained')){$taskRow=Read-TaskMember ('cloud_job/campaign/native/evaluation/case_0045/'+$taskArm+'/case_receipt.json');Assert-TaskSeconds $taskRow.wall_seconds;if($taskRow.case_index -ne 45 -or $taskRow.arm -ne $taskArm){throw 'CASE45_ARM_MAPPING'};$taskCase45+=@{arm=$taskArm;status=$taskRow.execution_status;wall_seconds=$taskRow.wall_seconds}}
$taskGrouped=@()
foreach($taskGroup in ($taskArms|Group-Object arm,status)){$taskDurations=@($taskGroup.Group|ForEach-Object {$_.wall_seconds});$taskStats=$taskDurations|Measure-Object -Sum -Minimum -Maximum -Average;$taskGrouped+=@{arm=$taskGroup.Group[0].arm;status=$taskGroup.Group[0].status;count=$taskGroup.Count;summed_wall_seconds=$taskStats.Sum;min_seconds=$taskStats.Minimum;max_seconds=$taskStats.Maximum;mean_seconds=$taskStats.Average}}
if($taskNative.separate_timeout_prefix.prefix.committed_native_runs -ne 37 -or $taskNative.separate_timeout_prefix.prefix.scheduled_program_native_runs -ne 39 -or $taskNative.outcomes.cases[45].reference.trace_count -ne 11){throw 'CASE45_PINNED_PREFIX_COUNTS_CHANGED'}
$taskCaseStats=$taskRows.case_wall_seconds|Measure-Object -Sum -Minimum -Maximum -Average
$taskReferenceStats=$taskRows.reference_wall_seconds|Measure-Object -Sum -Minimum -Maximum -Average
$taskProcess=Read-TaskMember 'cloud_job/campaign/processes/evaluate/process_receipt.json'
$taskPrefix=git rev-parse --show-prefix
$taskSourcePins=@{}
foreach($taskFile in @('cas_meta2/contrast_v7/native_evaluation.py','cas_meta2/contrast_recovery_v6/core.py')){if((git hash-object --no-filters -- $taskFile) -ne (git rev-parse ('42f9164754312f12850d9b8789c062fa7fb8069f:'+$taskPrefix+$taskFile))){throw 'FROZEN_TIMING_SOURCE_CHANGED'};$taskSourcePins[$taskFile]=(Get-FileHash -Algorithm SHA256 -LiteralPath $taskFile).Hash.ToLower()}
foreach($taskMember in $taskMembers.Keys){if((Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $taskInputRoot $taskMember)).Hash.ToLower() -ne $taskMembers[$taskMember]){throw 'INPUT_CHANGED_DURING_RECOUNT'}}
if($taskRows.Count -ne 71 -or $taskArms.Count -ne 355){throw 'TIMING_COVERAGE'}
@{schema='cas-meta2-v7-recorded-native-timing/1';status='RECORDED_PARTIAL_TIMING_RECOUNT_PASSED';utc=(Get-Date).ToUniversalTime().ToString('o');job=$taskNative.job;source_sha=$taskNative.source_sha;receipt_pins=$taskPins;source_files_sha256=$taskSourcePins;input_member_sha256=$taskMembers;recorded_case_count=71;recorded_arm_count_in_completed_cases=355;case45_saved_arms=$taskCase45;case45_reference_runs=$taskNative.outcomes.cases[45].reference.trace_count;case45_committed_candidate_runs=37;case45_selected_candidate_runs=39;case45_candidate_total_seconds=$null;case45_worker_start_time=$null;case_rows=$taskRows;arm_groups=$taskGrouped;case_seconds=@{sum=$taskCaseStats.Sum;min=$taskCaseStats.Minimum;max=$taskCaseStats.Maximum;mean=$taskCaseStats.Average};reference_seconds=@{sum=$taskReferenceStats.Sum;min=$taskReferenceStats.Minimum;max=$taskReferenceStats.Maximum;mean=$taskReferenceStats.Average};native_process_wall_seconds=$taskProcess.wall_seconds;source_pool_max_workers=8;model_or_provider_work=$false;inputs_rehashed_after=$true;runtime_root_cause_established=$false;boundary='Recount of recorded elapsed times only. Case workers overlap; summed worker seconds are not elapsed campaign time or billing. Arm times include admission, execution or failure-prefix checking, verification, identity checks and result writes as defined by frozen core.py. No per-tick GPU profile or unfinished arm duration is available. Does not prove a deadlock, exact scheduler timing or hardware bottleneck.'}|ConvertTo-Json -Compress -Depth 8
